def compute(vars):
    remaining_capacity = vars["v1"]
    amount_added = vars["v2"]

    if amount_added == 0:
        return None

    value = (remaining_capacity / amount_added) * 100

    return {
        "value": value,
        "trace": {
            "remaining_capacity": remaining_capacity,
            "amount_added": amount_added,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
